    private fun parseChunk(chunk: String): List<String> =
        chunk.split(' ', '\n', '\r', '\t')
            .asSequence()
            .map { TurkishText.trNormalize(it) }
            .filter { it.length >= 3 }
            .toList()

    /** Curated 5-letter common Turkish words for Kelime Düellosu targets. */
    val wordleTargets: List<String> by lazy {
        listOf(
            TARGETS_5_CHUNK_1, TARGETS_5_CHUNK_2, TARGETS_5_CHUNK_3,
            TARGETS_5_CHUNK_4, TARGETS_5_CHUNK_5, TARGETS_5_CHUNK_6,
        )
            .flatMap { parseChunk(it) }
            .filter { it.length == 5 }
            .distinct()
    }

    /** Valid 5-letter guesses (target pool + all 5-letter words from the broader Turkish lexicon). */
    val validWords5: Set<String> by lazy {
        buildSet {
            addAll(wordleTargets)
            allChainWords.forEach { if (it.length == 5) add(it) }
        }
    }

    /** Broad offline Turkish dictionary (3..12 letters) for WordChain and WordDuel validation. */
    val allChainWords: Set<String> by lazy {
        buildSet {
            addAll(wordleTargets)
            listOf(
                EXTRA_CHAIN_CHUNK_1, EXTRA_CHAIN_CHUNK_2, EXTRA_CHAIN_CHUNK_3, EXTRA_CHAIN_CHUNK_4,
                EXTRA_CHAIN_CHUNK_5, EXTRA_CHAIN_CHUNK_6, EXTRA_CHAIN_CHUNK_7, EXTRA_CHAIN_CHUNK_8,
            ).forEach { chunk -> addAll(parseChunk(chunk)) }
        }
    }

    /** Clean starter words for WordChain (never ending in 'Ğ'). */
    private val chainStarters: List<String> by lazy {
        listOf(
            "KİTAP", "ARABA", "DENİZ", "GÜNEŞ", "KALEM", "ÇİÇEK", "BULUT", "ORMAN", "MÜZİK", "KAHVE",
            "BAHAR", "YILDIZ", "RÜZGAR", "KÖPRÜ", "LİMAN", "ŞEKER", "HAYAL", "ZAMAN", "DÜNYA", "ŞARKI",
            "ELMA", "MASA", "KAPI", "PENCERE", "BALIK", "KARTAL", "YAPRAK", "TOPRAK", "ŞEHİR", "NEHİR",
        ).map { TurkishText.trNormalize(it) }
    }

    fun pickTarget5(seed: String): String {
        val list = wordleTargets
        return list[Sha256.deterministicIndex("word5|$seed", list.size)]
    }

    fun pickStarterWord(seed: String): String {
        val list = chainStarters
        return list[Sha256.deterministicIndex("chain|$seed", list.size)]
    }

    fun isValidWord5(word: String): Boolean {
        val n = TurkishText.trNormalize(word)
        return n.length == 5 && n in validWords5
    }

    fun isValidChainWord(word: String): Boolean {
        val n = TurkishText.trNormalize(word)
        return n.length >= 3 && n in allChainWords
    }
}
